[Fact]
public async Task RunTaskAsync_Completion_MovesRelayDirToCompleted()
{
    using var repo = TestRepository.Create();
    repo.WriteConfig("dotnet test", []);
    repo.WriteTask("cleanup-test", "# Task for cleanup test\n");

    var sink = new InMemoryRelayEventSink();
    var runner = new ArtifactWritingSubagentRunner();
    runner.SeedHappyPath("src/cleanup.cs", "tests/cleanup.tests.cs");
    var driver = new RelayDriver(
        RelayDriverTestHelpers.DepsFor(repo, runner, new ScriptedTestRunner(
            new TestRunResult(1, "red"),
            new TestRunResult(0, "green")), sink),
        RelayDriverOptions.NoGitCommit);

    var outcome = await driver.RunTaskAsync(repo.Root, "cleanup-test");
    Assert.Equal(RelayTaskOutcomeStatus.Committed, outcome.Status);

    // The .relay/<taskId>/ directory must be moved to .relay/completed/<taskId>-<runId>/
    var relayDir = Path.Combine(repo.Root, ".relay");
    var taskDir = Path.Combine(relayDir, "cleanup-test");
    Assert.False(Directory.Exists(taskDir),
        ".relay/<taskId>/ should be moved to .relay/completed/ on completion");

    var completedDir = Path.Combine(relayDir, "completed");
    var completedDirs = Directory.GetDirectories(completedDir, "cleanup-test-*");
    Assert.Single(completedDirs);

    var archive = completedDirs[0];
    Assert.True(File.Exists(Path.Combine(archive, "status.json")));
    Assert.True(File.Exists(Path.Combine(archive, "cleanup-test.seals")));
    Assert.True(File.Exists(Path.Combine(archive, "ledger.md")));
    Assert.True(File.Exists(Path.Combine(archive, "manifest.txt")));
}

